    int argb();
}

package dev.pathland.core.protocol;

/** Value types for {@code PARAMETER::SET_PROPERTY} (mirrors {@code pathland_core::value_type}). */
public final class ValueTypes {
    public static final int U8 = 0x01;
    public static final int U32 = 0x02;
    public static final int I32 = 0x03;
    public static final int F32 = 0x04;
    public static final int STRING = 0x05;
    public static final int ENUM = 0x06;
    public static final int COLOR = 0x07;
    public static final int DESIGN_TOKEN = 0x08;
    public static final int LIST = 0x09;

    private ValueTypes() {
    }

    /** The protocol value type for a property id (mirrors {@code value_type_for}). */
    public static int forProperty(int prop) {
        switch (prop) {
            case Properties.COLOR:
            case Properties.BACKGROUND_COLOR:
            case Properties.BORDER_COLOR:
            case Properties.COLOR_MULTIPLY:
            case Properties.SHADOW_COLOR:
            case Properties.COLOR_VALUE:
            case Properties.TINT:
                return COLOR;
            case Properties.EVENT_LISTENERS:
            case Properties.BORDER_EDGES:
                return U32;
            case Properties.SELECTED:
            case Properties.VISIBLE:
            case Properties.ENABLED:
            case Properties.UNDERLINE:
            case Properties.STRIKETHROUGH:
            case Properties.COLOR_INVERT:
            case Properties.CLIPS_TO_BOUNDS:
            case Properties.ALLOWS_HIT_TESTING:
            case Properties.IS_SECURE:
            case Properties.IS_INDETERMINATE:
            case Properties.FIXED_SIZE_HORIZONTAL:
            case Properties.FIXED_SIZE_VERTICAL:
            case Properties.MEDIA_MUTED:
            case Properties.MEDIA_LOOP:
                return U8;
            case Properties.LABEL:
            case Properties.PROMPT:
            case Properties.FONT_FAMILY:
            case Properties.IMAGE_SOURCE:
            case Properties.MEDIA_SOURCE:
            case Properties.ROUTE:
            case Properties.ICON_NAME:
            case Properties.GRID_TRACKS:
                return STRING;
            case Properties.LINE_LIMIT:
            case Properties.SELECTION:
            case Properties.ACTION_ID:
            case Properties.BINDING_ID:
            case Properties.NAV_DEPTH:
            case Properties.PLAYBACK_STATE:
            case Properties.MEDIA_CONTROLLER_ID:
                return U32;
            case Properties.FIT_QUERY:
                return LIST;
            case Properties.ALIGNMENT:
            case Properties.TEXT_ALIGNMENT:
            case Properties.TRUNCATION_MODE:
            case Properties.TEXT_CASE:
            case Properties.FONT_STYLE:
            case Properties.FONT_DESIGN:
            case Properties.CONTENT_MODE:
            case Properties.CONTROL_SIZE:
            case Properties.SHAPE_KIND:
            case Properties.DATE_PICKER_MODE:
            case Properties.PICKER_STYLE:
            case Properties.TOGGLE_STYLE:
                return F32;
            default:
                return F32;
        }
    }
}

package dev.pathland.core.protocol;

/** Encodes typed property values into their raw 32-bit wire payload. */
public final class ValueEncoder {
    private ValueEncoder() {
    }

    /** Encode a typed value into its raw 32-bit wire payload for {@code SET_PROPERTY}. */
    public static int encodeBits(int valueType, Object value) {
        switch (valueType) {
            case ValueTypes.F32:
                return Float.floatToRawIntBits((Float) value);
            case ValueTypes.COLOR:
                return ((ColorValue) value).argb();
            case ValueTypes.U8:
            case ValueTypes.U32:
            case ValueTypes.ENUM:
                return ((Integer) value).intValue();
            default:
                throw new IllegalArgumentException("cannot encode value type " + valueType);
        }
    }
}

package dev.pathland.core.transport;

import dev.pathland.core.protocol.Opcode;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * A self-contained frame: 16-byte opcodes plus its own string section. STRING
 * payloads reference strings by a relative offset, so a frame decodes with no
 * prior state.
 */
public final class ProtocolFrame {
    public static final ProtocolFrame EMPTY =
            new ProtocolFrame(Collections.emptyList(), new byte[0]);

    private final List<Opcode> opcodes;
    private final byte[] strings;

    public ProtocolFrame(List<Opcode> opcodes, byte[] strings) {
        this.opcodes = opcodes;
        this.strings = strings;
    }

    public List<Opcode> opcodes() {
        return opcodes;
    }

    public byte[] strings() {
        return strings;
    }

    public List<Opcode> getOpcodes() {
        return opcodes;
    }

    public byte[] getStrings() {
        return strings;
    }

    public boolean isEmpty() {
        return opcodes.isEmpty();
    }

    /** Read a length-prefixed string at a relative offset in the string section. */
    public String stringAt(int offset) {
        int len = readIntLE(strings, offset);
        return new String(strings, offset + 4, len, StandardCharsets.UTF_8);
    }

    private static int readIntLE(byte[] bytes, int offset) {
        return (bytes[offset] & 0xFF)
                | ((bytes[offset + 1] & 0xFF) << 8)
                | ((bytes[offset + 2] & 0xFF) << 16)
                | ((bytes[offset + 3] & 0xFF) << 24);
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof ProtocolFrame)) {
            return false;
        }
        ProtocolFrame that = (ProtocolFrame) other;
        return opcodes.equals(that.opcodes) && Arrays.equals(strings, that.strings);
    }

    @Override
    public int hashCode() {
        return 31 * opcodes.hashCode() + Arrays.hashCode(strings);
    }

    @Override
    public String toString() {
        return "ProtocolFrame(opcodes=" + opcodes + ", strings=" + strings.length + " bytes)";
    }
}

package dev.pathland.core.transport;

import dev.pathland.core.protocol.Commands;

import java.util.Objects;

/** A raw input event flowing host to guest through the EVENT opcode. */
public final class Event {
    private final int command;
    private final int target;
    private final int flags;
    private final float x;
    private final float y;
    private final float value;
    private final String text;
    private final int b;
    private final int c;

    public Event(
            int command,
            int target,
            int flags,
            float x,
            float y,
            float value,
            String text,
            int b,
            int c) {
        this.command = command;
        this.target = target;
        this.flags = flags;
        this.x = x;
        this.y = y;
        this.value = value;
        this.text = text;
        this.b = b;
        this.c = c;
    }

    public int command() {
        return command;
    }

    public int target() {
        return target;
    }

    public int flags() {
        return flags;
    }

    public float x() {
        return x;
    }

    public float y() {
        return y;
    }

    public float value() {
        return value;
    }

    public String text() {
        return text;
    }

    public int b() {
        return b;
    }

    public int c() {
        return c;
    }

    public int getCommand() {
        return command;
    }

    public int getTarget() {
        return target;
    }

    public int getFlags() {
        return flags;
    }

    public float getX() {
        return x;
    }

    public float getY() {
        return y;
    }

    public float getValue() {
        return value;
    }

    public String getText() {
        return text;
    }

    public int getB() {
        return b;
    }

    public int getC() {
        return c;
    }

    public boolean isPointerDown() {
        return command == Commands.Event.POINTER_DOWN;
    }

    public boolean isPointerMove() {
        return command == Commands.Event.POINTER_MOVE;
    }

    public boolean isPointerUp() {
        return command == Commands.Event.POINTER_UP;
    }

    public boolean isKeyDown() {
        return command == Commands.Event.KEY_DOWN;
    }

    public boolean isKeyUp() {
        return command == Commands.Event.KEY_UP;
    }

    public boolean isValueChanged() {
        return command == Commands.Event.VALUE_CHANGED;
    }

    public boolean isTextChanged() {
        return command == Commands.Event.TEXT_CHANGED;
    }

    public boolean isFocusChanged() {
        return command == Commands.Event.FOCUS_CHANGED;
    }

    public boolean isEditingChanged() {
        return command == Commands.Event.EDITING_CHANGED;
    }

    public boolean isSubmit() {
        return command == Commands.Event.SUBMIT;
    }

    public boolean isScroll() {
        return command == Commands.Event.SCROLL;
    }

    public boolean isWheel() {
        return command == Commands.Event.WHEEL;
    }

    public boolean isDateChanged() {
        return command == Commands.Event.DATE_CHANGED;
    }

    public boolean isNavigate() {
        return command == Commands.Event.NAVIGATE;
    }

    public boolean isMediaPlayStateChanged() {
        return command == Commands.Event.MEDIA_PLAY_STATE_CHANGED;
    }

    public boolean isMediaTimeUpdated() {
        return command == Commands.Event.MEDIA_TIME_UPDATED;
    }

    public boolean isMediaEnded() {
        return command == Commands.Event.MEDIA_ENDED;
    }

    public boolean isMediaVolumeChanged() {
        return command == Commands.Event.MEDIA_VOLUME_CHANGED;
    }

    public boolean isMediaDurationChanged() {
        return command == Commands.Event.MEDIA_DURATION_CHANGED;
    }

    public boolean isFitChanged() {
        return command == Commands.Event.FIT_CHANGED;
    }

    public boolean mediaPlaying() {
        return b != 0;
    }

    public float mediaValue() {
        return value;
    }

    public int fitIndex() {
        return Math.round(value);
    }

    public String url() {
        return text;
    }

    public boolean isNavigateBack() {
        return isNavigate() && (flags & Commands.Flags.NAVIGATE_URL) == 0;
    }

    public int keyCode() {
        return b;
    }

    public int modifiers() {
        return c;
    }

    public int days() {
        return b;
    }

    public int millisOfDay() {
        return c;
    }

    public static Event pointerDown(int target, float x, float y) {
        return new Event(Commands.Event.POINTER_DOWN, target, 0, x, y, 0f, null, 0, 0);
    }

    public static Event pointerUp(int target, float x, float y) {
        return new Event(Commands.Event.POINTER_UP, target, 0, x, y, 0f, null, 0, 0);
    }

    public static Event pointerMove(int target, float x, float y, int flags) {
        return new Event(Commands.Event.POINTER_MOVE, target, flags, x, y, 0f, null, 0, 0);
    }

    public static Event keyDown(int target, int keyCode, int modifiers, int flags) {
        return new Event(Commands.Event.KEY_DOWN, target, flags, 0f, 0f, 0f, null, keyCode, modifiers);
    }

    public static Event keyUp(int target, int keyCode, int modifiers) {
        return new Event(Commands.Event.KEY_UP, target, 0, 0f, 0f, 0f, null, keyCode, modifiers);
    }

    public static Event valueChanged(int target, float value) {
        return new Event(Commands.Event.VALUE_CHANGED, target, 0, 0f, 0f, value, null, 0, 0);
    }

    public static Event textChanged(int target, String text) {
        return new Event(Commands.Event.TEXT_CHANGED, target, 0, 0f, 0f, 0f, text, 0, 0);
    }

    public static Event focusChanged(int target, boolean focused) {
        return new Event(Commands.Event.FOCUS_CHANGED, target, 0, 0f, 0f, 0f, null,
                focused ? 1 : 0, 0);
    }

    public static Event editingChanged(int target, boolean editing) {
        return new Event(Commands.Event.EDITING_CHANGED, target, 0, 0f, 0f, 0f, null,
                editing ? 1 : 0, 0);
    }

    public static Event submit(int target) {
        return new Event(Commands.Event.SUBMIT, target, 0, 0f, 0f, 0f, null, 0, 0);
    }

    public static Event scroll(int target, float offsetX, float offsetY) {
        return new Event(Commands.Event.SCROLL, target, 0, offsetX, offsetY, 0f, null, 0, 0);
    }

    public static Event wheel(int target, float deltaX, float deltaY) {
        return new Event(Commands.Event.WHEEL, target, 0, deltaX, deltaY, 0f, null, 0, 0);
    }

    public static Event dateChanged(int target, int days, int millisOfDay) {
        return new Event(Commands.Event.DATE_CHANGED, target, 0, 0f, 0f, 0f, null, days, millisOfDay);
    }

    public static Event navigate(String url) {
        return new Event(Commands.Event.NAVIGATE, 0, Commands.Flags.NAVIGATE_URL,
                0f, 0f, 0f, url, 0, 0);
    }

    public static Event navigateBack() {
        return new Event(Commands.Event.NAVIGATE, 0, 0, 0f, 0f, 0f, null, 0, 0);
    }

    public static Event mediaPlayStateChanged(int target, boolean playing) {
        return new Event(Commands.Event.MEDIA_PLAY_STATE_CHANGED, target, 0, 0f, 0f, 0f, null,
                playing ? 1 : 0, 0);
    }

    public static Event mediaTimeUpdated(int target, float seconds) {
        return new Event(Commands.Event.MEDIA_TIME_UPDATED, target, 0, 0f, 0f, seconds, null, 0, 0);
    }

    public static Event mediaEnded(int target) {
        return new Event(Commands.Event.MEDIA_ENDED, target, 0, 0f, 0f, 0f, null, 0, 0);
    }

    public static Event mediaVolumeChanged(int target, float volume) {
        return new Event(Commands.Event.MEDIA_VOLUME_CHANGED, target, 0, 0f, 0f, volume, null, 0, 0);
    }

    public static Event mediaDurationChanged(int target, float seconds) {
        return new Event(Commands.Event.MEDIA_DURATION_CHANGED, target, 0, 0f, 0f, seconds, null, 0, 0);
    }

    public static Event fitChanged(int target, float index) {
        return new Event(Commands.Event.FIT_CHANGED, target, 0, 0f, 0f, index, null, 0, 0);
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof Event)) {
            return false;
        }
        Event that = (Event) other;
        return command == that.command
                && target == that.target
                && flags == that.flags
                && Float.compare(x, that.x) == 0
                && Float.compare(y, that.y) == 0
                && Float.compare(value, that.value) == 0
                && Objects.equals(text, that.text)
                && b == that.b
                && c == that.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(command, target, flags, x, y, value, text, b, c);
    }

    @Override
    public String toString() {
        return "Event(command=" + command + ", target=" + target + ", flags=" + flags
                + ", x=" + x + ", y=" + y + ", value=" + value + ", text=" + text
                + ", b=" + b + ", c=" + c + ")";
    }
}

package dev.pathland.core.transport;

/**
 * The platform's environment data: viewport size and the initial route, delivered
 * as {@code META::ENVIRONMENT} fields.
 */
public final class EnvironmentData {
    private final String route;
    private final float viewportWidth;
    private final float viewportHeight;

    public EnvironmentData(String route, float viewportWidth, float viewportHeight) {
        this.route = normalize(route);
        this.viewportWidth = viewportWidth;
        this.viewportHeight = viewportHeight;
    }

    public String route() {
        return route;
    }

    public float viewportWidth() {
        return viewportWidth;
    }

    public float viewportHeight() {
        return viewportHeight;
    }

    public String getRoute() {
        return route;
    }

    public float getViewportWidth() {
        return viewportWidth;
    }

    public float getViewportHeight() {
        return viewportHeight;
    }

    public static EnvironmentData of(String route) {
        return new EnvironmentData(route, -1f, -1f);
    }

    private static String normalize(String route) {
        String normalized = (route == null || route.isBlank()) ? "/" : route;
        if (!normalized.startsWith("/")) {
            normalized = "/" + normalized;
        }
        return normalized;
    }
}

package dev.pathland.core.transport;

import dev.pathland.core.text.AttributedString;

/**
 * The emission target for opcodes: a self-contained frame sink (SSR/WebSocket) or
 * the zero-copy Rust ring sink.
 */
public interface OpcodeSink {
    void beginFrame();

    void endFrame();

    void createNode(int id, int component);

    void deleteNode(int id);

    void insertChild(int parent, int child, int index);

    void removeChild(int parent, int child);

    void moveChild(int parent, int child, int newIndex);

    void setText(int nodeId, String text);

    void setAttributedText(int nodeId, AttributedString value);

    void setProperty(int nodeId, int property, int valueType, Object value);

    void setDate(int nodeId, int days, int millisOfDay);

    void setDesignToken(String path, int valueType, Object value);

    /** Clear every application design-token override. */
    default void resetTheme() {
        throw new UnsupportedOperationException("resetTheme");
    }

    /** Emit {@code META::SET_COLOR_SCHEME} (0 platform, 1 light, 2 dark). */
    default void setColorScheme(int mode) {
        throw new UnsupportedOperationException("setColorScheme");
    }

    /** Emit {@code META::SET_WINDOW_METADATA}; an empty string clears the field. */
    default void setWindowMetadata(int field, String value) {
        throw new UnsupportedOperationException("setWindowMetadata");
    }

    /** Whether this sink feeds a renderer that gates raw inputs on a {@code BINDING_ID}. */
    default boolean requiresBindingId() {
        return false;
    }
}

package dev.pathland.core.transport;

import dev.pathland.core.protocol.Categories;
import dev.pathland.core.protocol.Commands;
import dev.pathland.core.protocol.Opcode;
import dev.pathland.core.protocol.TokenPath;
import dev.pathland.core.protocol.ValueEncoder;
import dev.pathland.core.protocol.ValueTypes;
import dev.pathland.core.text.AttributedString;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/** An {@link OpcodeSink} that accumulates a self-contained {@link ProtocolFrame}. */
public class FrameOpcodeSink implements OpcodeSink {
    private final List<Opcode> opcodes = new ArrayList<>();
    private final ByteArrayOutputStream strings = new ByteArrayOutputStream();
    private ProtocolFrame frame = ProtocolFrame.EMPTY;
    private int framesProduced = 0;

    public ProtocolFrame frame() {
        return frame;
    }

    public int framesProduced() {
        return framesProduced;
    }

    public boolean hasChanges() {
        return !opcodes.isEmpty();
    }

    @Override
    public void beginFrame() {
        opcodes.clear();
        strings.reset();
    }

    @Override
    public void endFrame() {
        frame = new ProtocolFrame(new ArrayList<>(opcodes), strings.toByteArray());
        framesProduced++;
    }

    @Override
    public void createNode(int id, int component) {
        push(Categories.TREE, Commands.Tree.CREATE_NODE, 0, id, component, 0);
    }

    @Override
    public void deleteNode(int id) {
        push(Categories.TREE, Commands.Tree.DELETE_NODE, 0, id, 0, 0);
    }

    @Override
    public void insertChild(int parent, int child, int index) {
        push(Categories.TREE, Commands.Tree.INSERT_CHILD, 0, parent, child, index);
    }

    @Override
    public void removeChild(int parent, int child) {
        push(Categories.TREE, Commands.Tree.REMOVE_CHILD, 0, parent, child, 0);
    }

    @Override
    public void moveChild(int parent, int child, int newIndex) {
        push(Categories.TREE, Commands.Tree.MOVE_CHILD, 0, parent, child, newIndex);
    }

    @Override
    public void setText(int nodeId, String text) {
        int offset = strings.size();
        writeString(text);
        push(Categories.PARAMETER, Commands.Parameter.SET_TEXT, 0, nodeId, offset, 0);
    }

    @Override
    public void setAttributedText(int nodeId, AttributedString value) {
        int offset = strings.size();
        byte[] payload = value.encode();
        writeIntLE(payload.length);
        strings.writeBytes(payload);
        push(Categories.PARAMETER, Commands.Parameter.SET_ATTRIBUTED_TEXT, 0, nodeId, offset, 0);
    }

    @Override
    public void setProperty(int nodeId, int property, int valueType, Object value) {
        int b = (valueType << 16) | (property & 0xFFFF);
        switch (valueType) {
            case ValueTypes.STRING: {
                int offset = strings.size();
                writeString((String) value);
                push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, offset);
                break;
            }
            case ValueTypes.DESIGN_TOKEN: {
                int offset = strings.size();
                String path = ((TokenPath) value).tokenPath();
                writeString(path == null ? "" : path);
                push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, offset);
                break;
            }
            case ValueTypes.LIST: {
                int offset = strings.size();
                float[] elements = (float[]) value;
                writeIntLE(elements.length);
                for (float element : elements) {
                    int bits = Float.floatToRawIntBits(element);
                    strings.write(bits & 0xFF);
                    strings.write((bits >>> 8) & 0xFF);
                    strings.write((bits >>> 16) & 0xFF);
                    strings.write((bits >>> 24) & 0xFF);
                }
                push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, offset);
                break;
            }
            default:
                push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b,
                        ValueEncoder.encodeBits(valueType, value));
                break;
        }
    }

    @Override
    public void setDate(int nodeId, int days, int millisOfDay) {
        push(Categories.PARAMETER, Commands.Parameter.SET_DATE, 0, nodeId, days, millisOfDay);
    }

    @Override
    public void setDesignToken(String path, int valueType, Object value) {
        int pathOffset = strings.size();
        writeString(path);
        int c;
        if (valueType == ValueTypes.STRING) {
            int offset = strings.size();
            writeString((String) value);
            c = offset;
        } else {
            c = ValueEncoder.encodeBits(valueType, value);
        }
        push(Categories.PARAMETER, Commands.Parameter.SET_DESIGN_TOKEN, 0, pathOffset, valueType, c);
    }

    public int writeString(String text) {
        int offset = strings.size();
        byte[] utf8 = text.getBytes(StandardCharsets.UTF_8);
        writeIntLE(utf8.length);
        strings.writeBytes(utf8);
        return offset;
    }

    private void push(int category, int command, int flags, int a, int b, int c) {
        opcodes.add(new Opcode(category, command, flags, a, b, c));
    }

    private void writeIntLE(int value) {
        strings.write(value & 0xFF);
        strings.write((value >>> 8) & 0xFF);
        strings.write((value >>> 16) & 0xFF);
        strings.write((value >>> 24) & 0xFF);
    }

    @Override
    public void resetTheme() {
        push(Categories.META, Commands.Meta.RESET_THEME, 0, 0, 0, 0);
    }

    @Override
    public void setColorScheme(int mode) {
        push(Categories.META, Commands.Meta.SET_COLOR_SCHEME, 0, mode, 0, 0);
    }

    @Override
    public void setWindowMetadata(int field, String value) {
        int offset = strings.size();
        writeString(value);
        push(Categories.META, Commands.Meta.SET_WINDOW_METADATA, 0, field, offset, 0);
    }
}

package dev.pathland.core.transport;

import dev.pathland.core.protocol.Categories;
import dev.pathland.core.protocol.Commands;
import dev.pathland.core.protocol.Opcode;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/** The network batch codec — mirrors {@code pathland_core_transport}. */
public final class FrameCodec {
    public static final int MAGIC = 0x504C_504C;
    public static final int VERSION = 1;
    public static final int GUEST_TO_HOST = 0x0000;
    public static final int HOST_TO_GUEST = 0x0001;
    public static final int HEADER = 16;

    private FrameCodec() {
    }

    /** Encode a self-contained frame as a network batch (sequence 0). */
    public static byte[] encodeFrame(ProtocolFrame frame) {
        return encodeFrame(frame, 0);
    }

    /** Encode a self-contained frame as a guest to host batch with {@code sequence}. */
    public static byte[] encodeFrame(ProtocolFrame frame, int sequence) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeHeader(out, GUEST_TO_HOST, sequence, frame.opcodes().size());
        for (Opcode op : frame.opcodes()) {
            writeBytes(out, op.toBytes());
        }
        writeIntLE(out, frame.strings().length);
        writeBytes(out, frame.strings());
        return out.toByteArray();
    }

    /** Decode a self-contained frame batch into opcodes and string section. */
    public static ProtocolFrame decodeFrame(byte[] bytes) {
        Parsed parsed = parse(bytes);
        return new ProtocolFrame(parsed.opcodes, parsed.strings);
    }

    /** The per-stream message sequence encoded in a batch header (offset 8). */
    public static int sequence(byte[] bytes) {
        if (bytes.length < HEADER) {
            throw new IllegalArgumentException("batch truncated");
        }
        return readIntLE(bytes, 8);
    }

    /** Encode a {@code META::RESYNC} request batch (host to guest). */
    public static byte[] encodeResync() {
        return singleMeta(Commands.Meta.RESYNC);
    }

    /** Encode a {@code META::PONG} reply batch (host to guest). */
    public static byte[] encodePong() {
        return singleMeta(Commands.Meta.PONG);
    }

    /** Encode a {@code META::PING} heartbeat probe batch (guest to host). */
    public static byte[] encodePing() {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeHeader(out, GUEST_TO_HOST, 0, 1);
        writeBytes(out, new Opcode(Categories.META, Commands.Meta.PING, 0, 0, 0, 0).toBytes());
        writeIntLE(out, 0);
        return out.toByteArray();
    }

    private static byte[] singleMeta(int command) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeHeader(out, HOST_TO_GUEST, 0, 1);
        writeBytes(out, new Opcode(Categories.META, command, 0, 0, 0, 0).toBytes());
        writeIntLE(out, 0);
        return out.toByteArray();
    }

    /** Encode a {@code META::ENVIRONMENT} field batch (viewport and route). */
    public static byte[] encodeEnvironment(EnvironmentData env) {
        byte[] route = env.route().getBytes(StandardCharsets.UTF_8);
        List<Opcode> ops = new ArrayList<>(3);
        if (env.viewportWidth() > 0) {
            ops.add(new Opcode(Categories.META, Commands.Meta.ENVIRONMENT, 0,
                    Commands.Environment.VIEWPORT_WIDTH,
                    Float.floatToRawIntBits(env.viewportWidth()), 0));
        }
        if (env.viewportHeight() > 0) {
            ops.add(new Opcode(Categories.META, Commands.Meta.ENVIRONMENT, 0,
                    Commands.Environment.VIEWPORT_HEIGHT,
                    Float.floatToRawIntBits(env.viewportHeight()), 0));
        }
        ops.add(new Opcode(Categories.META, Commands.Meta.ENVIRONMENT, 0,
                Commands.Environment.ROUTE, 0, 0));
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeHeader(out, HOST_TO_GUEST, 0, ops.size());
        for (Opcode op : ops) {
            writeBytes(out, op.toBytes());
        }
        writeIntLE(out, 4 + route.length);
        writeIntLE(out, route.length);
        out.writeBytes(route);
        return out.toByteArray();
    }

    /** True when the batch is a {@code META::RESYNC} request. */
    public static boolean isResync(byte[] bytes) {
        return parse(bytes).opcodes.stream().anyMatch(
                op -> op.category() == Categories.META
                        && op.command() == Commands.Meta.RESYNC);
    }

    /** True when the batch carries a {@code META::PING} heartbeat probe. */
    public static boolean isPing(byte[] bytes) {
        return parse(bytes).opcodes.stream().anyMatch(
                op -> op.category() == Categories.META
                        && op.command() == Commands.Meta.PING);
    }

    /** True when the batch carries {@code META::ENVIRONMENT} fields. */
    public static boolean isEnvironment(byte[] bytes) {
        return parse(bytes).opcodes.stream().anyMatch(
                op -> op.category() == Categories.META
                        && op.command() == Commands.Meta.ENVIRONMENT);
    }

    /** Decode a {@code META::ENVIRONMENT} field batch into {@link EnvironmentData}. */
    public static EnvironmentData decodeEnvironment(byte[] bytes) {
        Parsed parsed = parse(bytes);
        String route = null;
        float width = -1f;
        float height = -1f;
        for (Opcode op : parsed.opcodes) {
            if (op.category() != Categories.META
                    || op.command() != Commands.Meta.ENVIRONMENT) {
                continue;
            }
            switch (op.a() & 0xFFFF) {
                case Commands.Environment.VIEWPORT_WIDTH:
                    width = Float.intBitsToFloat(op.b());
                    break;
                case Commands.Environment.VIEWPORT_HEIGHT:
                    height = Float.intBitsToFloat(op.b());
                    break;
                case Commands.Environment.ROUTE:
                    route = parsed.stringAt(op.b());
                    break;
                default:
                    break;
            }
        }
        return new EnvironmentData(route, width, height);
    }

    /** Encode host to guest events as a batch. */
    public static byte[] encodeEvents(List<Event> events) {
        List<Opcode> opcodes = new ArrayList<>(events.size());
        ByteArrayOutputStream strings = new ByteArrayOutputStream();
        for (Event event : events) {
            if (event.isTextChanged()) {
                int offset = strings.size();
                byte[] utf8 = (event.text() == null ? "" : event.text())
                        .getBytes(StandardCharsets.UTF_8);
                writeIntLE(strings, utf8.length);
                strings.writeBytes(utf8);
                opcodes.add(new Opcode(
                        Categories.EVENT, Commands.Event.TEXT_CHANGED, 0, event.target(), offset, 0));
            } else if (event.isNavigate()) {
                if (event.isNavigateBack()) {
                    opcodes.add(new Opcode(Categories.EVENT, Commands.Event.NAVIGATE, 0, 0, 0, 0));
                } else {
                    int offset = strings.size();
                    byte[] utf8 = (event.url() == null ? "" : event.url())
                            .getBytes(StandardCharsets.UTF_8);
                    writeIntLE(strings, utf8.length);
                    strings.writeBytes(utf8);
                    opcodes.add(new Opcode(Categories.EVENT, Commands.Event.NAVIGATE,
                            Commands.Flags.NAVIGATE_URL, 0, offset, 0));
                }
            } else if (event.isValueChanged()) {
                opcodes.add(new Opcode(Categories.EVENT, Commands.Event.VALUE_CHANGED, 0,
                        event.target(), Float.floatToRawIntBits(event.value()), 0));
            } else if (event.isKeyDown() || event.isKeyUp()) {
                opcodes.add(new Opcode(Categories.EVENT, event.command(), event.flags(),
                        event.target(), event.b(), event.c()));
            } else if (event.isDateChanged()) {
                opcodes.add(new Opcode(Categories.EVENT, Commands.Event.DATE_CHANGED, 0,
                        event.target(), event.b(), event.c()));
            } else if (event.isFocusChanged()
                    || event.isEditingChanged()
                    || event.isSubmit()) {
                opcodes.add(new Opcode(Categories.EVENT, event.command(), 0,
                        event.target(), event.b(), 0));
            } else if (event.isMediaTimeUpdated()
                    || event.isMediaVolumeChanged()
                    || event.isMediaDurationChanged()
                    || event.isFitChanged()) {
                opcodes.add(new Opcode(Categories.EVENT, event.command(), 0,
                        event.target(), Float.floatToRawIntBits(event.value()), 0));
            } else if (event.isMediaPlayStateChanged() || event.isMediaEnded()) {
                opcodes.add(new Opcode(Categories.EVENT, event.command(), 0,
                        event.target(), event.b(), 0));
            } else {
                opcodes.add(new Opcode(Categories.EVENT, event.command(), event.flags(),
                        event.target(), Float.floatToRawIntBits(event.x()),
                        Float.floatToRawIntBits(event.y())));
            }
        }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeHeader(out, HOST_TO_GUEST, 0, opcodes.size());
        for (Opcode op : opcodes) {
            writeBytes(out, op.toBytes());
        }
        writeIntLE(out, strings.size());
        writeBytes(out, strings.toByteArray());
        return out.toByteArray();
    }

    /** Decode a host to guest event batch into typed events. */
    public static List<Event> decodeEvents(byte[] bytes) {
        Parsed parsed = parse(bytes);
        List<Event> events = new ArrayList<>();
        for (Opcode op : parsed.opcodes) {
            if (op.category() != Categories.EVENT) {
                continue;
            }
            switch (op.command()) {
                case Commands.Event.TEXT_CHANGED:
                    events.add(Event.textChanged(op.a(), parsed.stringAt(op.b())));
                    break;
                case Commands.Event.NAVIGATE:
                    events.add((op.flags() & Commands.Flags.NAVIGATE_URL) != 0
                            ? Event.navigate(parsed.stringAt(op.b()))
                            : Event.navigateBack());
                    break;
                case Commands.Event.VALUE_CHANGED:
                    events.add(Event.valueChanged(op.a(), Float.intBitsToFloat(op.b())));
                    break;
                case Commands.Event.KEY_DOWN:
                    events.add(Event.keyDown(op.a(), op.b(), op.c(), op.flags()));
                    break;
                case Commands.Event.KEY_UP:
                    events.add(Event.keyUp(op.a(), op.b(), op.c()));
                    break;
                case Commands.Event.DATE_CHANGED:
                    events.add(Event.dateChanged(op.a(), op.b(), op.c()));
                    break;
                case Commands.Event.FOCUS_CHANGED:
                    events.add(Event.focusChanged(op.a(), op.b() != 0));
                    break;
                case Commands.Event.EDITING_CHANGED:
                    events.add(Event.editingChanged(op.a(), op.b() != 0));
                    break;
                case Commands.Event.SUBMIT:
                    events.add(Event.submit(op.a()));
                    break;
                case Commands.Event.SCROLL:
                    events.add(Event.scroll(op.a(), Float.intBitsToFloat(op.b()),
                            Float.intBitsToFloat(op.c())));
                    break;
                case Commands.Event.WHEEL:
                    events.add(Event.wheel(op.a(), Float.intBitsToFloat(op.b()),
                            Float.intBitsToFloat(op.c())));
                    break;
                case Commands.Event.MEDIA_PLAY_STATE_CHANGED:
                    events.add(Event.mediaPlayStateChanged(op.a(), op.b() != 0));
                    break;
                case Commands.Event.MEDIA_TIME_UPDATED:
                    events.add(Event.mediaTimeUpdated(op.a(), Float.intBitsToFloat(op.b())));
                    break;
                case Commands.Event.MEDIA_ENDED:
                    events.add(Event.mediaEnded(op.a()));
                    break;
                case Commands.Event.MEDIA_VOLUME_CHANGED:
                    events.add(Event.mediaVolumeChanged(op.a(), Float.intBitsToFloat(op.b())));
                    break;
                case Commands.Event.MEDIA_DURATION_CHANGED:
                    events.add(Event.mediaDurationChanged(op.a(), Float.intBitsToFloat(op.b())));
                    break;
                case Commands.Event.FIT_CHANGED:
                    events.add(Event.fitChanged(op.a(), Float.intBitsToFloat(op.b())));
                    break;
                case Commands.Event.POINTER_DOWN:
                case Commands.Event.POINTER_MOVE:
                case Commands.Event.POINTER_UP:
                    events.add(new Event(op.command(), op.a(), op.flags(),
                            Float.intBitsToFloat(op.b()), Float.intBitsToFloat(op.c()),
                            0f, null, 0, 0));
                    break;
                default:
                    break;
            }
        }
        return events;
    }

    private static final class Parsed {
        final List<Opcode> opcodes;
        final byte[] strings;

        Parsed(List<Opcode> opcodes, byte[] strings) {
            this.opcodes = opcodes;
            this.strings = strings;
        }

        String stringAt(int offset) {
            if (offset < 0 || (long) offset + 4L > (long) strings.length) {
                throw new IllegalArgumentException("string offset out of bounds");
            }
            long len = readUInt32LE(strings, offset);
            long start = (long) offset + 4L;
            if (start + len > (long) strings.length) {
                throw new IllegalArgumentException("string length out of bounds");
            }
            return new String(strings, (int) start, (int) len, StandardCharsets.UTF_8);
        }
    }

    private static Parsed parse(byte[] bytes) {
        if (bytes.length < HEADER) {
            throw new IllegalArgumentException("batch truncated");
        }
        int magic = readIntLE(bytes, 0);
        if (magic != MAGIC) {
            throw new IllegalArgumentException(
                    "bad batch magic 0x" + Integer.toHexString(magic));
        }
        int version = (bytes[4] & 0xFF) | ((bytes[5] & 0xFF) << 8);
        if (version != VERSION) {
            throw new IllegalArgumentException("unsupported batch version " + version);
        }
        // The opcode count is an attacker-controlled u32. Compute with Long and
        // validate against the actual message length BEFORE allocating, so a
        // declared count cannot overflow Int arithmetic into a small end offset
        // and then trigger a huge ArrayList allocation (OOM).
        long opcodeCount = readUInt32LE(bytes, 12);
        long opcodesEnd = (long) HEADER + opcodeCount * (long) Opcode.SIZE;
        if (opcodesEnd + 4L > (long) bytes.length) {
            throw new IllegalArgumentException("batch truncated (opcodes)");
        }
        if (opcodeCount > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("opcode count out of range");
        }
        int opcodeCountInt = (int) opcodeCount;
        List<Opcode> opcodes = new ArrayList<>(opcodeCountInt);
        for (int i = 0; i < opcodeCountInt; i++) {
            byte[] slot = new byte[Opcode.SIZE];
            System.arraycopy(bytes, HEADER + i * Opcode.SIZE, slot, 0, Opcode.SIZE);
            opcodes.add(Opcode.fromBytes(slot));
        }
        long stringsLen = readUInt32LE(bytes, (int) opcodesEnd);
        long stringsStart = opcodesEnd + 4L;
        if (stringsStart + stringsLen > (long) bytes.length) {
            throw new IllegalArgumentException("batch truncated (strings)");
        }
        if (stringsLen > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("string section out of range");
        }
        int stringsLenInt = (int) stringsLen;
        byte[] strings = new byte[stringsLenInt];
        System.arraycopy(bytes, (int) stringsStart, strings, 0, stringsLenInt);
        return new Parsed(opcodes, strings);
    }

    private static void writeHeader(
            ByteArrayOutputStream out, int flags, int sequence, int opcodeCount) {
        writeIntLE(out, MAGIC);
        writeShortLE(out, VERSION);
        writeShortLE(out, flags);
        writeIntLE(out, sequence);
        writeIntLE(out, opcodeCount);
    }

    private static void writeIntLE(ByteArrayOutputStream out, int value) {
        out.write(value & 0xFF);
        out.write((value >>> 8) & 0xFF);
        out.write((value >>> 16) & 0xFF);
        out.write((value >>> 24) & 0xFF);
    }

    private static void writeShortLE(ByteArrayOutputStream out, int value) {
        out.write(value & 0xFF);
        out.write((value >>> 8) & 0xFF);
    }

    private static void writeBytes(ByteArrayOutputStream out, byte[] bytes) {
        out.writeBytes(bytes);
    }

    private static int readIntLE(byte[] bytes, int offset) {
        return (bytes[offset] & 0xFF)
                | ((bytes[offset + 1] & 0xFF) << 8)
                | ((bytes[offset + 2] & 0xFF) << 16)
                | ((bytes[offset + 3] & 0xFF) << 24);
    }

    /** Read a little-endian u32 as a non-negative Long (no sign/overflow surprises). */
    private static long readUInt32LE(byte[] bytes, int offset) {
        return (bytes[offset] & 0xFFL)
                | ((bytes[offset + 1] & 0xFFL) << 8)
                | ((bytes[offset + 2] & 0xFFL) << 16)
                | ((bytes[offset + 3] & 0xFFL) << 24);
    }
}

package dev.pathland.core.text;

import dev.pathland.core.protocol.Properties;
import dev.pathland.core.protocol.ValueTypes;

import java.util.Objects;

/**
 * A scalar text-format attribute on a range.
 *
 * <p>{@code value} is the standard 4-byte wire value (an {@code F32} bit pattern
 * for float attributes, a packed {@code 0xAARRGGBB} for colors, {@code 0}/{@code 1}
 * for booleans).
 */
public final class TextAttribute {
    private final int property;
    private final int valueType;
    private final int value;

    public TextAttribute(int property, int valueType, int value) {
        this.property = property;
        this.valueType = valueType;
        this.value = value;
    }

    public TextAttribute(int property, int value) {
        this(property, ValueTypes.forProperty(property), value);
    }

    public int property() {
        return property;
    }

    public int valueType() {
        return valueType;
    }

    public int value() {
        return value;
    }

    public int getProperty() {
        return property;
    }

    public int getValueType() {
        return valueType;
    }

    public int getValue() {
        return value;
    }

    public static TextAttribute fontSize(float points) {
        return new TextAttribute(Properties.FONT_SIZE, ValueTypes.F32,
                Float.floatToRawIntBits(points));
    }

    public static TextAttribute fontWeight(float weight) {
        return new TextAttribute(Properties.FONT_WEIGHT, ValueTypes.F32,
                Float.floatToRawIntBits(weight));
    }

    public static TextAttribute color(int argb) {
        return new TextAttribute(Properties.COLOR, ValueTypes.COLOR, argb);
    }

    public static TextAttribute italic() {
        return new TextAttribute(Properties.FONT_STYLE, ValueTypes.F32,
                Float.floatToRawIntBits(1.0f));
    }

    public static TextAttribute fontDesign(int code) {
        return new TextAttribute(Properties.FONT_DESIGN, ValueTypes.F32,
                Float.floatToRawIntBits((float) code));
    }

    public static TextAttribute underline() {
        return underline(true);
    }

    public static TextAttribute underline(boolean on) {
        return new TextAttribute(Properties.UNDERLINE, ValueTypes.U8, on ? 1 : 0);
    }

    public static TextAttribute strikethrough() {
        return strikethrough(true);
    }

    public static TextAttribute strikethrough(boolean on) {
        return new TextAttribute(Properties.STRIKETHROUGH, ValueTypes.U8, on ? 1 : 0);
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof TextAttribute)) {
            return false;
        }
        TextAttribute that = (TextAttribute) other;
        return property == that.property
                && valueType == that.valueType
                && value == that.value;
    }

    @Override
    public int hashCode() {
        return Objects.hash(property, valueType, value);
    }

    @Override
    public String toString() {
        return "TextAttribute(property=" + property + ", valueType=" + valueType
                + ", value=" + value + ")";
    }
}

package dev.pathland.core.text;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/** A range of the text with a set of scalar attributes (UTF-8 byte offsets). */
public final class StyleRun {
    private final int start;
    private final int end;
    private final List<TextAttribute> attributes;

    public StyleRun(int start, int end, List<TextAttribute> attributes) {
        this.start = start;
        this.end = end;
        this.attributes = attributes;
    }

    public int start() {
        return start;
    }

    public int end() {
        return end;
    }

    public List<TextAttribute> attributes() {
        return attributes;
    }

    public int getStart() {
        return start;
    }

    public int getEnd() {
        return end;
    }

    public List<TextAttribute> getAttributes() {
        return attributes;
    }

    public StyleRun bold() {
        return adding(TextAttribute.fontWeight(700f));
    }

    public StyleRun italic() {
        return adding(TextAttribute.italic());
    }

    public StyleRun monospaced() {
        return adding(TextAttribute.fontDesign(3));
    }

    public StyleRun strikethrough() {
        return adding(TextAttribute.strikethrough());
    }

    public StyleRun underline() {
        return adding(TextAttribute.underline());
    }

    private StyleRun adding(TextAttribute attribute) {
        List<TextAttribute> next = new ArrayList<>(attributes);
        next.add(attribute);
        return new StyleRun(start, end, Collections.unmodifiableList(next));
    }

    public static StyleRun of(int start, int end) {
        return new StyleRun(start, end, Collections.emptyList());
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof StyleRun)) {
            return false;
        }
        StyleRun that = (StyleRun) other;
        return start == that.start && end == that.end
                && Objects.equals(attributes, that.attributes);
    }

    @Override
    public int hashCode() {
        return Objects.hash(start, end, attributes);
    }

    @Override
    public String toString() {
        return "StyleRun(start=" + start + ", end=" + end
                + ", attributes=" + attributes + ")";
    }
}

