Index: lib/java/pathland-core/src/test/java/dev/pathland/core/protocol/ProtocolManifestTest.java
===================================================================
--- lib/java/pathland-core/src/test/java/dev/pathland/core/protocol/ProtocolManifestTest.java	
+++ lib/java/pathland-core/src/test/java/dev/pathland/core/protocol/ProtocolManifestTest.java	
@@ -0,0 +1,160 @@
+package dev.pathland.core.protocol;
+
+import org.junit.jupiter.api.Test;
+
+import java.io.IOException;
+import java.lang.reflect.Field;
+import java.lang.reflect.Modifier;
+import java.nio.charset.StandardCharsets;
+import java.nio.file.Files;
+import java.nio.file.Path;
+import java.util.ArrayList;
+import java.util.HashMap;
+import java.util.HashSet;
+import java.util.List;
+import java.util.Map;
+import java.util.Set;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+/**
+ * Validates the hand-written JVM protocol constant classes against the neutral
+ * {@code spec/protocol.tsv} manifest emitted from the canonical Rust constants.
+ *
+ * <p>No Java source is generated. This test is the drift guard: add or renumber a
+ * Rust constant, regenerate the manifest, and either update the Java mirror or
+ * this suite fails with the exact row that drifted.
+ */
+class ProtocolManifestTest {
+
+    private static final String COMMANDS = "dev.pathland.core.protocol.Commands$";
+    private static final Set<String> KINDS = Set.of(
+            "category", "component", "command", "field", "flag", "listener",
+            "size", "value_type", "property", "property_value_type");
+
+    @Test
+    void manifestIsWellFormed() throws IOException {
+        List<Row> rows = rows();
+        Set<String> keys = new HashSet<>();
+        Set<String> propertyNames = new HashSet<>();
+        Set<String> valueTypeNames = new HashSet<>();
+
+        for (Row row : rows) {
+            assertTrue(KINDS.contains(row.kind()), "unknown manifest kind: " + row.kind());
+            assertTrue(keys.add(row.kind() + "/" + row.group() + "/" + row.name()),
+                    "duplicate manifest row: " + row);
+            if (row.kind().equals("property")) {
+                propertyNames.add(row.name());
+            } else if (row.kind().equals("value_type")) {
+                valueTypeNames.add(row.name());
+            }
+        }
+
+        Set<String> mappedProperties = new HashSet<>();
+        for (Row row : rows) {
+            if (row.kind().equals("property_value_type")) {
+                assertTrue(propertyNames.contains(row.name()),
+                        "value-type mapping for unknown property: " + row.name());
+                assertTrue(valueTypeNames.contains(row.value()),
+                        "unknown value type in mapping: " + row);
+                assertTrue(mappedProperties.add(row.name()),
+                        "duplicate value-type mapping: " + row.name());
+            }
+        }
+
+        assertEquals(propertyNames, mappedProperties,
+                "every property must have exactly one property_value_type row");
+    }
+
+    @Test
+    void javaConstantsMatchManifest() throws Exception {
+        Map<Class<?>, Set<String>> expected = new HashMap<>();
+        for (Row row : rows()) {
+            if (row.kind().equals("property_value_type")) {
+                continue;
+            }
+            expected.computeIfAbsent(targetClass(row), ignored -> new HashSet<>()).add(row.name());
+            Field field = targetClass(row).getField(row.name());
+            Object actual = field.get(null);
+            Object wanted = field.getType() == float.class
+                    ? (Object) Float.parseFloat(row.value())
+                    : (Object) Integer.decode(row.value());
+            assertEquals(wanted, actual, row.kind() + " " + row.name());
+        }
+
+        for (Map.Entry<Class<?>, Set<String>> entry : expected.entrySet()) {
+            for (Field field : entry.getKey().getDeclaredFields()) {
+                int mods = field.getModifiers();
+                if (Modifier.isPublic(mods)
+                        && Modifier.isStatic(mods)
+                        && (field.getType() == int.class || field.getType() == float.class)) {
+                    assertTrue(entry.getValue().contains(field.getName()),
+                            "Java constant has no manifest row: "
+                                    + entry.getKey().getSimpleName() + "." + field.getName());
+                }
+            }
+        }
+    }
+
+    @Test
+    void valueTypeMappingMatchesManifest() throws Exception {
+        for (Row row : rows()) {
+            if (!row.kind().equals("property_value_type")) {
+                continue;
+            }
+            int property = ((Number) Properties.class.getField(row.name()).get(null)).intValue();
+            int expected = ((Number) ValueTypes.class.getField(row.value()).get(null)).intValue();
+            assertEquals(expected, ValueTypes.forProperty(property),
+                    "ValueTypes.forProperty(" + row.name() + ")");
+        }
+    }
+
+    private static Class<?> targetClass(Row row) throws ClassNotFoundException {
+        return switch (row.kind()) {
+            case "category" -> Categories.class;
+            case "component" -> Components.class;
+            case "property" -> Properties.class;
+            case "value_type" -> ValueTypes.class;
+            case "command", "field", "flag", "listener", "size" ->
+                    Class.forName(COMMANDS + row.group());
+            default -> throw new IllegalArgumentException("unknown manifest kind: " + row.kind());
+        };
+    }
+
+    private static List<Row> rows() throws IOException {
+        Path manifest = locateManifest();
+        List<Row> rows = new ArrayList<>();
+        for (String line : Files.readAllLines(manifest, StandardCharsets.UTF_8)) {
+            if (line.isBlank() || line.startsWith("#")) {
+                continue;
+            }
+            String[] parts = line.split("\t", -1);
+            assertEquals(4, parts.length, "bad manifest row: " + line);
+            rows.add(new Row(parts[0], parts[1], parts[2], parts[3]));
+        }
+        assertFalse(rows.isEmpty(), "manifest is empty: " + manifest);
+        return rows;
+    }
+
+    private static Path locateManifest() {
+        Path dir = Path.of(System.getProperty("user.dir")).toAbsolutePath();
+        while (dir != null) {
+            Path candidate = dir.resolve("spec/protocol.tsv");
+            if (Files.isRegularFile(candidate)) {
+                return candidate;
+            }
+            dir = dir.getParent();
+        }
+        throw new IllegalStateException(
+                "could not locate spec/protocol.tsv from " + System.getProperty("user.dir"));
+    }
+
+    private record Row(String kind, String group, String name, String value) {
+        @Override
+        public String toString() {
+            return kind + "/" + group + "/" + name + "=" + value;
+        }
+    }
+}

Index: lib/java/pathland-core/src/test/java/dev/pathland/core/transport/FrameCodecTest.java
===================================================================
--- lib/java/pathland-core/src/test/java/dev/pathland/core/transport/FrameCodecTest.java	
+++ lib/java/pathland-core/src/test/java/dev/pathland/core/transport/FrameCodecTest.java	
@@ -0,0 +1,126 @@
+package dev.pathland.core.transport;
+
+import dev.pathland.core.protocol.Categories;
+import dev.pathland.core.protocol.Commands;
+import dev.pathland.core.protocol.Opcode;
+import org.junit.jupiter.api.Test;
+
+import java.nio.ByteBuffer;
+import java.nio.ByteOrder;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertThrows;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+/**
+ * The network batch codec's transport-liveness helpers: {@code META::PING}
+ * detection and the {@code META::PONG} reply (spec/OPCODE.md §Transport
+ * heartbeat — network batch transport only).
+ */
+class FrameCodecTest {
+
+    @Test
+    void encodePongProducesASingleMetaPongBatch() {
+        byte[] bytes = FrameCodec.encodePong();
+        ProtocolFrame frame = FrameCodec.decodeFrame(bytes);
+        assertEquals(1, frame.opcodes().size());
+        Opcode op = frame.opcodes().get(0);
+        assertEquals(Categories.META, op.category());
+        assertEquals(Commands.Meta.PONG, op.command());
+        assertEquals(0, op.a());
+        assertEquals(0, op.b());
+        assertEquals(0, op.c());
+    }
+
+    @Test
+    void encodePingProducesASingleMetaPingBatch() {
+        byte[] bytes = FrameCodec.encodePing();
+        assertTrue(FrameCodec.isPing(bytes), "encodePing is detected as a PING");
+        ProtocolFrame frame = FrameCodec.decodeFrame(bytes);
+        Opcode op = frame.opcodes().get(0);
+        assertEquals(Categories.META, op.category());
+        assertEquals(Commands.Meta.PING, op.command());
+    }
+
+    @Test
+    void encodeEnvironmentRoundTripsViewportAndRoute() {
+        byte[] bytes = FrameCodec.encodeEnvironment(new EnvironmentData("/kitchen", 1280f, 800f));
+        assertTrue(FrameCodec.isEnvironment(bytes), "encodeEnvironment is detected as an environment batch");
+        EnvironmentData env = FrameCodec.decodeEnvironment(bytes);
+        assertEquals("/kitchen", env.route());
+        assertEquals(1280f, env.viewportWidth());
+        assertEquals(800f, env.viewportHeight());
+    }
+
+    @Test
+    void encodeEnvironmentWithUnknownViewportEmitsOnlyTheRouteField() {
+        byte[] bytes = FrameCodec.encodeEnvironment(EnvironmentData.of("/"));
+        ProtocolFrame frame = FrameCodec.decodeFrame(bytes);
+        assertEquals(1, frame.opcodes().size(), "no viewport fields when the viewport is unknown");
+        assertEquals(Commands.Environment.ROUTE, frame.opcodes().get(0).a() & 0xFFFF);
+    }
+
+    @Test
+    void encodeFrameStampsAndReadsTheMessageSequence() {
+        ProtocolFrame frame = new ProtocolFrame(
+                java.util.List.of(new Opcode(Categories.TREE, Commands.Tree.CREATE_NODE, 0, 1, 0x10, 0)),
+                new byte[0]);
+        byte[] delta = FrameCodec.encodeFrame(frame, 7);
+        assertEquals(7, FrameCodec.sequence(delta), "a delta batch carries its sequence");
+        // The 1-arg overload is for non-delta batches (heartbeat/requests): sequence 0.
+        assertEquals(0, FrameCodec.sequence(FrameCodec.encodeFrame(frame)));
+    }
+
+    @Test
+    void rejectsAnOpcodeCountThatWouldOverflowIntArithmetic() {
+        // 0x20000000 * 16 overflows Int to 0. The decoder must reject it using
+        // Long arithmetic before allocating the opcode list (an OOM DoS).
+        byte[] bytes = batchHeader(0x20000000, 0);
+        assertThrows(IllegalArgumentException.class, () -> FrameCodec.decodeFrame(bytes));
+    }
+
+    @Test
+    void rejectsAHugeStringSectionLength() {
+        // 20 bytes: header + the stringsLen field. A u32 stringsLen == -1 as an
+        // Int must not reach ByteArray allocation.
+        byte[] bytes = batchHeader(0, 0xFFFFFFFF);
+        assertThrows(IllegalArgumentException.class, () -> FrameCodec.decodeFrame(bytes));
+    }
+
+    @Test
+    void rejectsAnOutOfBoundsStringOffset() {
+        ProtocolFrame frame = new ProtocolFrame(
+                java.util.List.of(new Opcode(
+                        Categories.EVENT, Commands.Event.TEXT_CHANGED, 0, 1, 999, 0)),
+                new byte[0]);
+        byte[] bytes = FrameCodec.encodeFrame(frame);
+        assertThrows(IllegalArgumentException.class, () -> FrameCodec.decodeEvents(bytes));
+    }
+
+    @Test
+    void isPingDetectsAMetaPingBatch() {
+        // A META::PING heartbeat probe (guest → host), the exact vector-16a bytes.
+        byte[] ping = new byte[16 + 16 + 4];
+        ByteBuffer view = ByteBuffer.wrap(ping).order(ByteOrder.LITTLE_ENDIAN);
+        view.putInt(0, FrameCodec.MAGIC);
+        view.putShort(4, (short) FrameCodec.VERSION);
+        view.putInt(12, 1); // opcodeCount
+        view.put(16, (byte) Categories.META);
+        view.put(17, (byte) Commands.Meta.PING);
+        assertTrue(FrameCodec.isPing(ping), "a META::PING batch is detected");
+        assertFalse(FrameCodec.isResync(ping), "a PING batch is not a RESYNC");
+        assertFalse(FrameCodec.isPing(FrameCodec.encodeResync()), "a RESYNC batch is not a PING");
+    }
+
+    /** A minimal batch: magic/version/counts plus the stringsLen field (no payload). */
+    private static byte[] batchHeader(int opcodeCount, int stringsLen) {
+        byte[] bytes = new byte[FrameCodec.HEADER + 4];
+        ByteBuffer view = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
+        view.putInt(0, FrameCodec.MAGIC);
+        view.putShort(4, (short) FrameCodec.VERSION);
+        view.putInt(12, opcodeCount);
+        view.putInt(FrameCodec.HEADER, stringsLen);
+        return bytes;
+    }
+}
