         assertTrue(countCreate(frame, Components.IMAGE) >= 3)
         assertTrue(anySetPropertyString(frame, Properties.IMAGE_SOURCE, COVER))
         assertEquals(1, countCreate(frame, Components.SIZE_THAT_FITS))
