             if (value == -2.0f) {
                 return "HUG";
             }
         }
         String name = enumName(prop, value);
         if (name != null) {
             return name;
         }
         return Format.f32(value);
     }

     private static String enumName(int prop, float value) {
         int code = Math.round(value);
