         out.write(bytes.length & 0xFF);
         out.write((bytes.length >>> 8) & 0xFF);
         out.write((bytes.length >>> 16) & 0xFF);
         out.write((bytes.length >>> 24) & 0xFF);
         out.writeBytes(bytes);
