         @Override
         public void send(byte[] bytes) {
             if (FrameCodec.isPing(bytes)) {
                 listener.onBinary(FrameCodec.encodePong());
             } else if (FrameCodec.isResync(bytes)) {
                 listener.onBinary(snapshot);
