         int proxyTarget = base() + 2;
         session.forwardEvent(Event.pointerMove(proxyTarget, 1f, 1f, 0));
         session.forwardEvent(Event.pointerMove(proxyTarget, 2f, 2f, 0));
         session.flushPendingEvents();

