                 .filter(b -> !FrameCodec.isEnvironment(b) && !FrameCodec.isResync(b)
                         && !FrameCodec.isPing(b))
                 .flatMap(b -> FrameCodec.decodeEvents(b).stream())
                 .filter(Event::isPointerMove)
                 .count();
